-- Seed: 40 dummy DJ accounts for the /djs listing page.
-- Run once in the Supabase SQL Editor. Safe to re-run (guarded by ON CONFLICT DO NOTHING),
-- except the dj_profiles insert which assumes a clean first run.
-- These are dummy auth.users rows (fake emails, unusable passwords) purely so
-- public.profiles.id can satisfy its foreign key to auth.users(id) — inserting
-- into auth.users fires the existing on_auth_user_created trigger, which
-- auto-creates the matching public.profiles row (role + display_name).

insert into auth.users (
  instance_id, id, aud, role, email, encrypted_password,
  email_confirmed_at, created_at, updated_at,
